def solve(inputs: dict) -> float:
    mod=int(inputs['MOD']); k=int(inputs['K'])
    m=[[int(inputs['A'])%mod,int(inputs['B'])%mod],[int(inputs['C'])%mod,int(inputs['D'])%mod]]
    r=[[1,0],[0,1]]
    def mul(x,y):
        return [[(x[0][0]*y[0][0]+x[0][1]*y[1][0])%mod,(x[0][0]*y[0][1]+x[0][1]*y[1][1])%mod],[(x[1][0]*y[0][0]+x[1][1]*y[1][0])%mod,(x[1][0]*y[0][1]+x[1][1]*y[1][1])%mod]]
    while k:
        if k&1:r=mul(r,m)
        m=mul(m,m);k//=2
    return float(sum(map(sum,r)))

