def solve(inputs: dict) -> float:
    x=int(inputs['X']); a=int(inputs['A']); b=int(inputs['B']); c=int(inputs['C']); k=int(inputs['K']); mask=(1<<32)-1
    for _ in range(k):
        x ^= (x << a) & mask
        x &= mask
        x ^= x >> b
        x &= mask
        x ^= (x << c) & mask
        x &= mask
    return float(x)

